SELECT 3012,1,'<invoice-rule@finance>','Finance: invoice and payee requirements for event expenses','finance@example.invalid','["wei.ran@example.invalid"]','[]','[]','2026-07-03T10:45:00+08:00','Three expense types require a company-header VAT invoice: charter bus, catering, and insurance. If the factory collects only a deposit, use its corporate account and retain the receipt. The payee name must match the contracting entity; if an account changes, pause and verify with the contract contact instead of paying from an email.','',0,1,0,'{}',3012,460,'2026-07-03T02:45:00Z'
WHERE NOT EXISTS (SELECT 1 FROM messages WHERE id = 3012)
  AND NOT EXISTS (SELECT 1 FROM messages WHERE message_id = '<invoice-rule@finance>');
